61	<main>
62	<h1>OpenSurvey</h1>
63	<p>问卷调查与反馈管理</p>
64	<div id="app"></div>
65	<p class="muted"><a href="/api/surveys">问卷列表接口</a> · <a href="/health">服务状态</a></p>
66	</main>
67	<script>
68	"use strict";
69	const app = document.getElementById("app");
70	
71	function h(tag, attrs, ...children) {
72	  const el = document.createElement(tag);
73	  if (attrs) for (const [k, v] of Object.entries(attrs)) {
74	    if (v === null || v === undefined) continue;
75	    if (k === "class") el.className = v;
76	    else if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
77	    else el.setAttribute(k, v);
78	  }
79	  for (const child of children.flat()) {
80	    if (child === null || child === undefined) continue;
81	    el.append(child.nodeType ? child : document.createTextNode(String(child)));
82	  }
83	  return el;
84	}
85	
86	/* ---------- 问卷表单（新建 / 编辑共用） ---------- */
87	
88	function buildSurveyForm(existing, hooks) {
89	  const mode = existing ? "edit" : "create";
90	
91	  const banner = h("div", {class: "banner", id: "form-banner"});
92	  banner.hidden = true;
93	
94	  const titleInput = h("input", {type: "text", id: "survey-title", maxlength: "200", placeholder: "请输入问卷标题"});
95	  const titleErr = h("p", {class: "field-err", id: "title-err"});
96	  const descArea = h("textarea", {id: "survey-desc", rows: "4", placeholder: "问卷说明（可留空，支持中文、引号与换行）"});
97	  const qBox = h("div", {id: "questions"});
98	  const qErr = h("p", {class: "field-err", id: "questions-err"});
99	
100	  function renumber() {
101	    const cards = qBox.querySelectorAll(".q-card");
102	    cards.forEach((card, i) => {
103	      card.querySelector(".q-index").textContent = `第 ${i + 1} 题`;
104	      card.querySelectorAll(".opt-row").forEach((row, j) => {
105	        row.querySelector(".opt-index").textContent = `选项 ${j + 1}`;
106	      });
107	    });
108	  }
109	
110	  function optionRow(value) {
111	    const text = h("input", {type: "text", class: "opt-text", placeholder: "选项内容"});
112	    if (value !== undefined && value !== null) text.value = value;
113	    const row = h("div", {class: "opt-row"},
114	      h("span", {class: "opt-index"}, "选项"),
115	      text,
116	      h("button", {type: "button", class: "link danger", onclick: () => { row.remove(); renumber(); }}, "删除")
117	    );
118	    return row;
119	  }
120	
121	  function addQuestion(type, prefill) {
122	    const isChoice = type === "single_choice";
123	    const options = h("div", {class: "options"});
124	    const card = h("div", {class: "card q-card", "data-type": type},
125	      h("div", {class: "q-head"},
126	        h("span", {class: "q-index"}, "第 N 题"),
127	        h("span", {class: "tag q-type-tag"}, isChoice ? "单选题" : "文本题"),
128	        h("label", {class: "req"},
129	          h("input", {type: "checkbox", class: "q-required"}), "必填（默认非必填）"),
130	        h("span", {class: "spacer"}),
131	        h("button", {type: "button", class: "link danger", onclick: () => { card.remove(); renumber(); }}, "删除本题")
132	      ),
133	      h("input", {type: "text", class: "q-title", placeholder: "题目标题"}),
134	      h("p", {class: "field-err q-title-err"})
135	    );
136	    if (isChoice) {
137	      const saved = prefill && Array.isArray(prefill.options) ? prefill.options : null;
138	      if (saved && saved.length) saved.forEach(value => options.append(optionRow(value)));
139	      else options.append(optionRow(), optionRow());
140	      card.append(
141	        options,
142	        h("p", {class: "field-err opt-err"}),
143	        h("button", {type: "button", class: "link add-opt"}, "添加选项")
144	      );
145	      card.querySelector(".add-opt").addEventListener("click", () => {
146	        options.append(optionRow());
147	        renumber();
148	        options.querySelector(".opt-row:last-child .opt-text").focus();
149	      });
150	    }
151	    if (prefill) {
152	      card.querySelector(".q-title").value = prefill.title != null ? prefill.title : "";
153	      card.querySelector(".q-required").checked = !!prefill.required;
154	    }
155	    qBox.append(card);
156	    renumber();
157	    if (!prefill) card.querySelector(".q-title").focus();
158	    return card;
159	  }
160	
161	  function clearErrors() {
162	    banner.hidden = true;
163	    banner.replaceChildren();
164	    titleErr.textContent = "";
165	    qErr.textContent = "";
166	    qBox.querySelectorAll(".invalid").forEach(el => el.classList.remove("invalid"));
167	    qBox.querySelectorAll(".field-err").forEach(el => { el.textContent = ""; });
168	  }
169	
170	  function showBanner(items) {
171	    banner.replaceChildren(h("strong", null, "问卷未能保存，请修改后重试："), h("ul", null,
172	      items.map(it => h("li", null, h("button", {type: "button", onclick: () => it.el && it.el.focus()}, it.msg)))));
173	    banner.hidden = false;
174	    banner.scrollIntoView({behavior: "smooth", block: "nearest"});
175	  }
176	
177	  const actionButtons = [
178	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("text")}, "添加文本题"),
179	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("single_choice")}, "添加单选题"),
180	    h("span", {class: "spacer"})
181	  ];
182	  if (mode === "edit") {
183	    // 离开编辑页即丢弃全部未保存的增删与输入
184	    actionButtons.push(h("a", {class: "btn secondary", href: `#/surveys/${existing.id}`}, "取消"));
185	  }
186	  actionButtons.push(h("button", {type: "submit", class: "btn"},
187	    mode === "edit" ? "保存修改" : "保存整份问卷"));
188	
189	  const form = h("form", {id: "draft-form", onsubmit: submitForm},
190	    banner,
191	    h("section", null,
192	      h("h2", null, mode === "edit" ? `编辑问卷草稿 #${existing.id}` : "新建问卷草稿"),
193	      mode === "edit"
194	        ? h("p", {class: "muted"}, "保存将整份替换当前草稿；取消则放弃本次修改，问卷编号和地址不变。")
195	        : null,
196	      h("label", {for: "survey-title"}, "标题"),
197	      titleInput, titleErr,
198	      h("label", {for: "survey-desc"}, "说明"),
199	      descArea,
200	      h("label", null, "题目（按下方顺序保存，至少保留一道题）"),
201	      qBox, qErr,
202	      h("div", {class: "row-actions"}, actionButtons)
203	    )
204	  );
205	
206	  if (mode === "edit") {
207	    titleInput.value = existing.title != null ? existing.title : "";
208	    descArea.value = existing.description || "";
209	    existing.questions.forEach(question => addQuestion(question.type, question));
210	    renumber();
211	  }
212	
213	  async function submitForm(event) {
214	    event.preventDefault();
215	    clearErrors();
216	    const problems = [];
217	
218	    const title = titleInput.value.trim();
219	    if (!title) {
220	      titleInput.classList.add("invalid");
221	      titleErr.textContent = "标题不能为空。";
222	      problems.push({el: titleInput, msg: "问卷标题不能为空。"});
223	    }
224	
225	    const cards = [...qBox.querySelectorAll(".q-card")];
226	    if (cards.length === 0) {
227	      qErr.textContent = "问卷至少需要保留一道题。";
228	      problems.push({el: qBox, msg: "问卷至少需要保留一道题，请先添加题目。"});
229	    }
230	
231	    const payloadQuestions = [];
232	    cards.forEach((card, i) => {
233	      const loc = `第 ${i + 1} 题`;
234	      const titleEl = card.querySelector(".q-title");
235	      const qTitle = titleEl.value.trim();
236	      if (!qTitle) {
237	        titleEl.classList.add("invalid");
238	        card.querySelector(".q-title-err").textContent = `${loc}：题目标题不能为空。`;
239	        problems.push({el: titleEl, msg: `${loc}：题目标题不能为空。`});
240	      }
241	      const q = {
242	        type: card.dataset.type,
243	        title: qTitle,
244	        required: card.querySelector(".q-required").checked
245	      };
246	      if (card.dataset.type === "single_choice") {
247	        const optInputs = [...card.querySelectorAll(".opt-text")];
248	        const values = optInputs.map(el => el.value.trim());
249	        const optErr = card.querySelector(".opt-err");
250	        const seen = new Set();
251	        values.forEach((val, j) => {
252	          if (!val) {
253	            optInputs[j].classList.add("invalid");
254	            optErr.textContent = `${loc}：第 ${j + 1} 个选项不能为空。`;
255	            problems.push({el: optInputs[j], msg: `${loc}：第 ${j + 1} 个选项不能为空。`});
256	          } else if (seen.has(val)) {
257	            optInputs[j].classList.add("invalid");
258	            optErr.textContent = `${loc}：选项“${val}”与同题其他选项重复。`;
259	            problems.push({el: optInputs[j], msg: `${loc}：选项“${val}”重复。`});
260	          }
261	          seen.add(val);
262	        });
263	        if (values.length < 2) {
264	          optErr.textContent = `${loc}：单选题至少需要两个选项。`;
265	          problems.push({el: card.querySelector(".add-opt"), msg: `${loc}：单选题至少需要两个选项。`});
266	        }
267	        q.options = values;
268	      }
269	      payloadQuestions.push(q);
270	    });
271	
272	    if (problems.length) {
273	      showBanner(problems);
274	      return;
275	    }
276	
277	    const payload = {title, description: descArea.value, questions: payloadQuestions};
278	    const endpoint = mode === "edit" ? `/api/surveys/${existing.id}` : "/api/surveys";
279	    let resp;
280	    try {
281	      resp = await fetch(endpoint, {
282	        method: mode === "edit" ? "PUT" : "POST",
283	        headers: {"Content-Type": "application/json"},
284	        body: JSON.stringify(payload)
285	      });
286	    } catch (err) {
287	      // 请求未成功：保留当前全部输入与增删结果
288	      showBanner([{el: null, msg: `网络错误，问卷尚未保存：${err}`}]);
289	      return;
290	    }
291	    let data = {};
292	    try { data = await resp.json(); } catch (_) { /* 保留已输入内容 */ }
293	    const saved = mode === "edit" ? resp.status === 200 : resp.status === 201;
294	    if (saved && data.id !== undefined) {
295	      if (mode === "create") {
296	        form.reset();
297	        qBox.replaceChildren();
298	        if (hooks && hooks.onCreated) hooks.onCreated();
299	      }
300	      location.hash = `#/surveys/${data.id}`;
301	      return;
302	    }
303	    // 服务端未确认保存成功：不清空任何输入，展示具体问题
304	    showBanner([{el: null, msg: data.error || `保存失败（HTTP ${resp.status}），问卷未保存，请检查后重试。`}]);
305	  }
306	
307	  return form;
308	}
