310	/* ---------- 首页 ---------- */
311	
312	function renderHome() {
313	  app.replaceChildren();
314	
315	  const listSection = h("section", null,
316	    h("h2", null, "问卷列表"),
317	    h("ul", {class: "plain", id: "survey-list"}, h("li", {class: "muted"}, "加载中…"))
318	  );
319	  const listEl = listSection.querySelector("#survey-list");
320	
321	  async function loadSurveys() {
322	    let data;
323	    try {
324	      const resp = await fetch("/api/surveys");
325	      data = await resp.json();
326	    } catch (err) {
327	      listEl.replaceChildren(h("li", {class: "muted"}, "问卷列表加载失败。"));
328	      return;
329	    }
330	    listEl.replaceChildren();
331	    if (!data.surveys.length) {
332	      listEl.append(h("li", {class: "muted"}, "还没有问卷记录。"));
333	      return;
334	    }
335	    for (const survey of data.surveys) {
336	      listEl.append(h("li", null,
337	        h("a", {href: `#/surveys/${survey.id}`}, `#${survey.id} ${survey.title}`)));
338	    }
339	  }
340	
341	  app.append(
342	    listSection,
343	    buildSurveyForm(null, {onCreated: loadSurveys})
344	  );
345	  loadSurveys();
346	}
347	
348	/* ---------- 问卷详情 ---------- */
349	
350	async function renderDetail(id) {
351	  app.replaceChildren(
352	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
353	    h("p", {class: "muted", id: "detail-status"}, "加载中…")
354	  );
355	  const status = document.getElementById("detail-status");
356	
357	  let survey;
358	  try {
359	    const resp = await fetch(`/api/surveys/${id}`);
360	    if (resp.status === 404) {
361	      status.textContent = `问卷 #${id} 不存在。`;
362	      return;
363	    }
364	    if (!resp.ok) {
365	      status.textContent = `详情加载失败（HTTP ${resp.status}），请稍后重试。`;
366	      return;
367	    }
368	    survey = await resp.json();
369	  } catch (err) {
370	    status.textContent = `详情加载失败：${err}`;
371	    return;
372	  }
373	
374	  app.replaceChildren(
375	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
376	    h("h2", null, `#${survey.id} ${survey.title}`),
377	    h("div", {class: "row-actions"},
378	      h("a", {class: "btn", href: `#/surveys/${survey.id}/edit`}, "编辑草稿"),
379	      h("a", {class: "btn secondary", href: "#/"}, "返回首页")
380	    ),
381	    h("h3", null, "说明"),
382	    survey.description
383	      ? h("p", {class: "detail-desc"}, survey.description)
384	      : h("p", {class: "muted"}, "（无说明）"),
385	    h("h3", null, `题目（共 ${survey.questions.length} 道）`)
386	  );
387	  if (!survey.questions.length) {
388	    app.append(
389	      h("p", {class: "muted"}, "该问卷草稿还没有题目，可进入编辑补齐。"),
390	      h("p", null, h("a", {class: "btn", href: `#/surveys/${survey.id}/edit`}, "编辑草稿并添加题目"))
391	    );
392	    return;
393	  }
394	  app.append(h("ol", {class: "q-list"},
395	    survey.questions.map((q, i) => h("li", null,
396	      h("div", {class: "q-line"},
397	        `${i + 1}. ${q.title} `,
398	        h("span", {class: "tag"}, q.type === "single_choice" ? "单选题" : "文本题"),
399	        " ",
400	        h("span", {class: "tag" + (q.required ? " required" : "")}, q.required ? "必填" : "选填")
401	      ),
402	      q.options && q.options.length
403	        ? h("ol", {start: "1"}, q.options.map(opt => h("li", {class: "opt-text-display"}, opt)))
404	        : null
405	    )))
406	  );
407	}
408	
409	/* ---------- 编辑草稿 ---------- */
410	
411	function showEditLoadError(id, message) {
412	  // 加载失败时明确提示，绝不能用空白编辑表单覆盖已有内容
413	  app.replaceChildren(
414	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
415	    h("h2", null, `编辑问卷草稿 #${id}`),
416	    h("div", {class: "banner", role: "alert"},
417	      h("strong", null, "问卷内容加载失败，未打开编辑表单："),
418	      h("p", {class: "detail-meta", style: "margin:.4rem 0 0"}, message),
419	      h("p", {style: "margin:.6rem 0 0"},
420	        h("button", {type: "button", class: "btn secondary", onclick: () => renderEdit(id)}, "重试"), " ",
421	        h("a", {class: "btn secondary", href: `#/surveys/${id}`}, "返回详情"))
422	    )
423	  );
424	}
425	
426	async function renderEdit(id) {
427	  app.replaceChildren(
428	    h("p", null, h("a", {href: `#/surveys/${id}`}, "← 返回问卷详情")),
429	    h("p", {class: "muted", id: "edit-status"}, "加载中…")
430	  );
431	
432	  let survey;
433	  try {
434	    const resp = await fetch(`/api/surveys/${id}`);
435	    if (resp.status === 404) {
436	      showEditLoadError(id, `问卷 #${id} 不存在。`);
437	      return;
438	    }
439	    if (!resp.ok) {
440	      showEditLoadError(id, `服务端返回异常（HTTP ${resp.status}），请稍后重试。`);
441	      return;
442	    }
443	    survey = await resp.json();
444	  } catch (err) {
445	    showEditLoadError(id, `网络错误：${err}。已保存的问卷内容未受影响，可重试加载。`);
446	    return;
447	  }
448	
449	  app.replaceChildren(
450	    h("p", null, h("a", {href: `#/surveys/${id}`}, "← 返回问卷详情")),
451	    buildSurveyForm(survey, {})
452	  );
453	}
454	
455	function route() {
456	  const editMatch = location.hash.match(/^#\/surveys\/(\d+)\/edit$/);
457	  const detailMatch = location.hash.match(/^#\/surveys\/(\d+)$/);
458	  if (editMatch) renderEdit(Number(editMatch[1]));
459	  else if (detailMatch) renderDetail(Number(detailMatch[1]));
460	  else renderHome();
461	}
462	window.addEventListener("hashchange", route);
463	route();
464	</script>
465	</html>
466	"""
