// 最小 DOM 桩 + fetch 控制器，验证 activeView 代数守卫
const calls = []; // {url, resolve, reject}
globalThis.fetch = (url) => new Promise((resolve, reject) => calls.push({url, resolve, reject}));

function makeEl(tag) {
  return {
    nodeType: 1, tagName: tag.toUpperCase(), children: [], attrs: {},
    class: '', style: {}, value: '', checked: false, hidden: false,
    textContent: '', innerHTML: '',
    set className(v) { this.class = v; },
    get className() { return this.class; },
    setAttribute(k, v) { this.attrs[k] = String(v); if (k === 'id') this.id = v; },
    addEventListener() {},
    append(...kids) { for (const k of kids.flat()) if (k != null) this.children.push(k); },
    replaceChildren(...kids) { this.children = kids.flat().filter(k => k != null); },
    scrollIntoView() {}, focus() {}, reset() {},
    querySelector(sel) { return find(this, sel, false); },
    querySelectorAll(sel) { return find(this, sel, true); },
  };
}
function matchClassTok(el, tok) {
  if (tok.startsWith('.')) return String(el.class || '').split(/\s+/).includes(tok.slice(1));
  if (tok.startsWith('#')) return el.id === tok.slice(1);
  return el.tagName === tok.toUpperCase();
}
function find(root, sel, all) {
  const toks = sel.trim().split(/\s+/).map(t => t.replace(/:[a-z-]+(\([^)]*\))?/g, ''));
  const last = toks[toks.length - 1];
  const out = [];
  (function walk(el) {
    for (const c of el.children || []) {
      if (c.nodeType === 1) { if (matchClassTok(c, last)) out.push(c); walk(c); }
    }
  })(root);
  if (all) { out.forEach ? null : null; return all === true ? out : out; }
  return out[0] || null;
}
const app = makeEl('main');
globalThis.document = {
  getElementById(id) {
    if (id === 'app') return app;
    const found = find(app, '#' + id, false);
    return found;
  },
  createElement: (t) => makeEl(t),
  createTextNode: (s) => ({nodeType: 3, textContent: String(s)}),
};
const listeners = {};
globalThis.window = { addEventListener: (ev, fn) => { (listeners[ev] = listeners[ev] || []).push(fn); } };
globalThis.location = { hash: '' };
function go(hash) {
  globalThis.location.hash = hash;
  listeners.hashchange.forEach(fn => fn());
}

const fs = require('fs');
eval(fs.readFileSync('/tmp/page.js', 'utf8')); // defines route, renderDetail, renderEdit...

function allText(el) {
  if (!el) return '';
  if (el.nodeType === 3) return el.textContent;
  let t = el.textContent && el.children.length === 0 ? el.textContent : '';
  return t + (el.children || []).map(allText).join('');
}
function appText() { return allText(app); }
let failures = 0;
function check(name, cond) { console.log((cond ? 'PASS' : 'FAIL') + ' - ' + name); if (!cond) failures++; }

const surveyA = {id: 1, title: '问卷甲', description: '甲的说明', questions: [
  {type: 'text', title: '甲的题目', required: true, options: []}]};
const surveyB = {id: 2, title: '问卷乙', description: '乙的说明', questions: [
  {type: 'single_choice', title: '乙的题目', required: false, options: ['乙选项1', '乙选项2']}]};
const jsonResp = (s, status = 200) => ({status, ok: status >= 200 && status < 300, json: async () => s});

(async () => {
  // 场景1：详情甲未完成 -> 详情乙先完成 -> 甲后完成，页面保持乙
  go('#/surveys/1');
  check('场景1 甲加载中', appText().includes('加载中'));
  go('#/surveys/2');
  check('场景1 切换乙后显示加载中', appText().includes('加载中') && !appText().includes('问卷甲'));
  const [a1, b1] = calls.splice(0, 2);
  b1.resolve(jsonResp(surveyB));
  await new Promise(r => setTimeout(r, 0));
  check('场景1 乙已显示标题', appText().includes('问卷乙'));
  check('场景1 乙显示题目与选项', appText().includes('乙的题目') && appText().includes('乙选项1'));
  a1.resolve(jsonResp(surveyA));
  await new Promise(r => setTimeout(r, 0));
  check('场景1 甲晚返回不覆盖', appText().includes('问卷乙') && !appText().includes('问卷甲') && !appText().includes('甲的题目'));

  // 场景2：编辑页加载中返回首页；随后编辑成功 / 失败均不能覆盖首页
  go('#/surveys/1/edit');
  const editCall = calls.shift();
  go('#/');
  const homeCall = calls.shift();
  homeCall.resolve(jsonResp({surveys: [{id: 1, title: '问卷甲'}, {id: 2, title: '问卷乙'}]}));
  await new Promise(r => setTimeout(r, 0));
  check('场景2 首页列表+新建表单', appText().includes('问卷列表') && appText().includes('新建问卷草稿') && appText().includes('问卷乙'));
  editCall.resolve(jsonResp(surveyA));
  await new Promise(r => setTimeout(r, 0));
  check('场景2 编辑成功晚到不重建表单', appText().includes('新建问卷草稿') && !appText().includes('编辑问卷草稿 #1'));
  check('场景2 首页列表仍在', appText().includes('问卷乙'));

  // 编辑失败也不能把首页换成错误提示
  go('#/surveys/1/edit');
  const editCall2 = calls.shift();
  go('#/');
  calls.shift().resolve(jsonResp({surveys: []}));
  await new Promise(r => setTimeout(r, 0));
  editCall2.resolve(jsonResp({error: 'not found'}, 404));
  await new Promise(r => setTimeout(r, 0));
  check('场景2 编辑404晚到不覆盖首页', appText().includes('新建问卷草稿') && !appText().includes('问卷内容加载失败'));
  editCall2.reject(new TypeError('network down')); // 已被消费，无效果；下面再测 reject 路径
  await new Promise(r => setTimeout(r, 0));

  // reject 路径：编辑加载中回首页，随后网络错误
  go('#/surveys/1/edit');
  const editCall3 = calls.shift();
  go('#/');
  calls.shift().resolve(jsonResp({surveys: []}));
  await new Promise(r => setTimeout(r, 0));
  editCall3.reject(new TypeError('Failed to fetch'));
  await new Promise(r => setTimeout(r, 0));
  check('场景2 编辑网络错误晚到不覆盖首页', appText().includes('新建问卷草稿') && !appText().includes('问卷内容加载失败'));

  // 场景3：离开同一问卷编辑页后重新进入；第一次加载更晚完成也不能重建表单
  go('#/surveys/1/edit');          // 第一次进入 v
  const first = calls.shift();
  go('#/surveys/1');               // 离开到详情
  calls.shift();                   // 详情请求（本次也会被后续切换作废）
  go('#/surveys/1/edit');          // 第二次进入同一份问卷
  const second = calls.shift();
  second.resolve(jsonResp({...surveyA, title: '第二次的标题', description: '第二次说明',
    questions: [{type: 'text', title: '第二次题目', required: false, options: []}]}));
  await new Promise(r => setTimeout(r, 0));
  check('场景3 当前编辑表单已带入第二次数据', appText().includes('编辑问卷草稿 #1'));
  const titleEl = document.getElementById('survey-title');
  check('场景3 标题为第二次加载结果', titleEl && titleEl.value === '第二次的标题');
  first.resolve(jsonResp({...surveyA, title: '第一次的标题'}));
  await new Promise(r => setTimeout(r, 0));
  check('场景3 第一次晚到不重建表单', document.getElementById('survey-title').value === '第二次的标题');
  // 模拟用户在本次编辑中已修改输入
  document.getElementById('survey-title').value = '用户正在输入的标题';
  first.resolve(jsonResp({...surveyA, title: '第一次的标题'}));
  await new Promise(r => setTimeout(r, 0));
  check('场景3 不清除用户已输入内容', document.getElementById('survey-title').value === '用户正在输入的标题');

  // 场景4：当前页面自己的加载仍正常工作（成功显示、失败给原提示、重试可用）
  go('#/surveys/999');
  calls.shift().resolve(jsonResp({error: 'not found'}, 404));
  await new Promise(r => setTimeout(r, 0));
  check('场景4 详情404原有提示', appText().includes('问卷 #999 不存在'));

  go('#/surveys/1/edit');
  calls.shift().resolve(jsonResp({error: 'err'}, 500));
  await new Promise(r => setTimeout(r, 0));
  check('场景4 编辑失败错误页（无空白表单）', appText().includes('问卷内容加载失败') && !appText().includes('保存修改'));
  // 点击重试：重新发起加载并成功
  listeners.hashchange; // noop
  // 直接触发重试按钮回调：从错误页 DOM 中不易取，改为调用内部绑定——通过再次 route 同等效果
  go('#/surveys/1'); go('#/surveys/1/edit');
  const retryCall = calls.shift();
  retryCall.resolve(jsonResp(surveyA));
  await new Promise(r => setTimeout(r, 0));
  check('场景4 重新进入编辑成功带入草稿', document.getElementById('survey-title') && document.getElementById('survey-title').value === '问卷甲');

  console.log(failures === 0 ? 'ALL PASS' : `${failures} FAILURES`);
  process.exit(failures === 0 ? 0 : 1);
})();
EOF
